def guarded_returns(pairs):
    returns = []
    bad = 0
    zero = 0
    for open_text, close_text in pairs:
        try:
            o = float(open_text)
            c = float(close_text)
        except ValueError:
            bad = bad + 1
            continue
        try:
            returns.append(c / o - 1)
        except ZeroDivisionError:
            zero = zero + 1
    return (returns, bad, zero)

